// Cell tags: plain-text chips a standard cell carries in the user's order.
// The client mirror of api/cell_tags.py (the server normalizes again and is
// the authority; its two limits are generated from there).
// A tag is trimmed, its inner whitespace collapsed to one space; a control
// character or more than TAG_MAX_LENGTH characters refuses it. A cell's
// list is unique under casefold, keeping the first spelling, and holds at
// most TAGS_PER_CELL_MAX tags.

// GENERATED by frontend/scripts/sync_app_constants.py from api/cell_tags.py; do not edit.
export const TAG_MAX_LENGTH = 48;
export const TAGS_PER_CELL_MAX = 32;
// END GENERATED

// Python's whitespace (str.isspace: what the server's strip() and re \s take):
// JS `\s` lacks \x1c-\x1f and \x85, and adds \ufeff, which Python keeps.
// eslint-disable-next-line no-control-regex -- \x1c-\x1f are whitespace to Python
const WHITESPACE = /[\t\n\v\f\r\x1c-\x1f \x85\xa0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]+/g;
// Unicode category Cc.
// eslint-disable-next-line no-control-regex -- control characters are what this refuses
const CONTROL = /[\x00-\x1f\x7f-\x9f]/;

/** One tag in its stored form, or null when it is empty, too long or
 *  carries a control character. */
export function normalizeTag(raw: string): string | null {
    // Collapse first, then drop the one space left at either end: String
    // trim() would also strip \ufeff, which str.strip() keeps.
    const tag = raw.replace(WHITESPACE, ' ').replace(/^ | $/g, '');
    if (!tag || CONTROL.test(tag)) return null;
    // Code points, as Python's len() counts them.
    if ([...tag].length > TAG_MAX_LENGTH) return null;
    return tag;
}

/** The comparison form: Python's casefold as near as JS comes (the upper
 *  pass folds ß to ss). */
export const foldTag = (tag: string): string => tag.toUpperCase().toLowerCase();

/** A cell's list in its stored form: each tag normalized, unique under
 *  casefold keeping the first spelling, in order. Throws, as the server
 *  refuses, on a non-list, a non-string, a refused tag or more than
 *  TAGS_PER_CELL_MAX. */
export function normalizeTags(raw: unknown): string[] {
    if (!Array.isArray(raw)) throw new TypeError('tags must be a list');
    const seen = new Set<string>();
    const out: string[] = [];
    for (const item of raw) {
        if (typeof item !== 'string') throw new TypeError('every tag must be a string');
        const tag = normalizeTag(item);
        if (tag === null) throw new RangeError(`tags are 1-${TAG_MAX_LENGTH} characters with no control characters`);
        const key = foldTag(tag);
        if (seen.has(key)) continue;
        seen.add(key);
        out.push(tag);
    }
    if (out.length > TAGS_PER_CELL_MAX) throw new RangeError(`a cell holds at most ${TAGS_PER_CELL_MAX} tags`);
    return out;
}

/** Does `tag` match what was typed (casefold substring; an empty query
 *  matches every tag)? */
export function tagMatches(query: string, tag: string): boolean {
    const q = foldTag(query.replace(WHITESPACE, ' ').replace(/^ | $/g, ''));
    return !q || foldTag(tag).includes(q);
}

/** Does `tags` hold `tag` under casefold? */
export const hasTag = (tags: readonly string[], tag: string): boolean => {
    const key = foldTag(tag);
    return tags.some(t => foldTag(t) === key);
};

type Tagged = { tags?: readonly string[] };

/** The tag vocabulary: every tag the board's cells, the loaded shelf and
 *  the vocabulary route name, unique under casefold (the first spelling in
 *  that order wins), sorted casefold. */
export function mergeVocabulary(
    liveCells: readonly Tagged[],
    removedEntries: readonly Tagged[] | null,
    fetched: readonly { tag: string }[] | null,
): string[] {
    const byKey = new Map<string, string>();
    const take = (raw: string) => {
        const tag = normalizeTag(raw);
        if (tag === null) return;
        const key = foldTag(tag);
        if (!byKey.has(key)) byKey.set(key, tag);
    };
    for (const cell of liveCells) for (const t of cell.tags ?? []) take(t);
    for (const entry of removedEntries ?? []) for (const t of entry.tags ?? []) take(t);
    for (const row of fetched ?? []) take(row.tag);
    return [...byKey.entries()]
        .sort(([a, ta], [b, tb]) => (a < b ? -1 : a > b ? 1 : ta < tb ? -1 : ta > tb ? 1 : 0))
        .map(([, tag]) => tag);
}
